    // Guard against invalid variable indices
    if (var < 1 || var > vars) return;

    // Increment activity with the given coefficient
    double delta = var_inc * coeff;
    activity[var] += delta;

    // Rescale all activities if any exceeds a safe upper bound
    const double ACTIVITY_LIMIT = 1e150;
    if (activity[var] > ACTIVITY_LIMIT) {
        const double RESCALE_FACTOR = 1e-150;
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= RESCALE_FACTOR;
        }
        var_inc *= RESCALE_FACTOR;
    }

    // Keep the VSIDS heap up‑to‑date
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}

